// The Worker's entry point (wrangler.jsonc "main"), new in W12: OpenNext's generated worker for every
// request, and the scheduled handler that runs reconcile every 5 minutes (server/scheduled.ts). As
// OpenNext documents for a custom worker (opennext.js.org/cloudflare/howtos/custom-worker): the generated
// file exists only after `opennextjs-cloudflare build`, which the deploy runs first.
// .open-next/worker.js is generated by the OpenNext build, so it may not exist when type checking: @ts-ignore,
// not @ts-expect-error, which would fail whenever the file does exist.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as openNext } from './.open-next/worker.js'
import { withScheduled } from './server/scheduled'

export default withScheduled(openNext)

// The Durable Object classes the generated worker exports (its queue, tag cache and cache purge), passed on.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- as above.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'
